function notice(text:string){setToast(text);setTimeout(()=>setToast(''),3500);}
useEffect(()=>{try{const saved=previewState?previewTheme:localStorage.getItem('shiftly-theme');if(saved&&['light','dark','system'].includes(saved))setTheme(saved);}catch{}const media=matchMedia('(prefers-color-scheme:dark)');const change=()=>setSystemDark(media.matches);change();media.addEventListener('change',change);return()=>media.removeEventListener('change',change);},[]);
const resolvedTheme=theme==='system'?(systemDark?'dark':'light'):theme;useEffect(()=>{const value=theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):theme;document.documentElement.dataset.theme=value;document.querySelectorAll('meta[name="theme-color"]').forEach(meta=>meta.setAttribute('content',value==='dark'?'#000000':'#f2f2f7'));try{if(!previewState)localStorage.setItem('shiftly-theme',theme);}catch{}},[theme,systemDark]);
useEffect(()=>{const url=new URL(location.href);if(url.searchParams.get('preview')==='phone')document.documentElement.dataset.phonePreview='true';if(url.searchParams.get('date')){const d=url.searchParams.get('date')==='today'?now:url.searchParams.get('date')!;if(/^\d{4}-\d{2}-\d{2}$/.test(d)){setSelected(d);setMonth(d.slice(0,7));}}if(url.searchParams.get('action')==='shift')setModal('day');if(url.searchParams.get('action')==='event'){setEditing(null);setModal('event');}if(url.searchParams.get('install')==='1')setModal('app');if(url.searchParams.get('invite')){setEditing(url.searchParams.get('invite'));setModal('accept');}},[]);
const start=month+'-01',end=useMemo(()=>{const d=new Date(start+'T12:00:00');d.setMonth(d.getMonth()+1);d.setDate(0);return dateKey(d);},[month]);
const settings=s?.calendar.settings||{},weekStart=settings.weekStart??1;
const cells=useMemo(()=>{const weekday=new Date(start+'T12:00:00').getDay();const first=addDays(start,-((weekday-weekStart+7)%7));const next=new Date(start+'T12:00:00Z');next.setUTCMonth(next.getUTCMonth()+1);next.setUTCDate(0);const count=Math.ceil((((weekday-weekStart+7)%7)+next.getUTCDate())/7)*7;return Array.from({length:count},(_,i)=>addDays(first,i));},[start,weekStart]);
