useEffect(()=>{const id=s?.calendar.settings?.overlayCalendar;if(!id||!identity){setOverlay(null);return;}let cancelled=false;const refresh=async()=>{try{const r=await fetch('/api/calendar?id='+encodeURIComponent(id));if(r.ok){const data=await r.json();if(!cancelled)setOverlay(data);}else if(!cancelled)setOverlay(null);}catch{}};refresh();const stream=new EventSource('/api/live?id='+encodeURIComponent(id));stream.onmessage=refresh;return()=>{cancelled=true;stream.close();};},[s?.calendar.settings?.overlayCalendar]);
