function finishRosterEdit(){setEditMode(false);setPaint('');setMulti(false);setDates([]);}
function startRosterEdit(){closeAll();setPage('Calendar');if(!['Month','Week'].includes(view))setView('Month');setEditMode(true);setPaint('');setMulti(true);setDates([]);}
function startPhonePaint(){if(editMode&&paint){finishRosterEdit();return;}closeAll();setEditMode(true);setMulti(false);setDates([]);setPaint(dayShift?.id||choices.find((shift:Shift)=>shift.category==='Work')?.id||choices[0]?.id||'__erase__');}
function pasteTarget(date:string){setSelected(date);setMonth(date.slice(0,7));setDates([]);}
useEffect(()=>{if(page!=='Calendar'||s?.role==='viewer')finishRosterEdit();},[page,s?.role]);
function chooseView(next:string){setView(next);if(!['Month','Week'].includes(next))finishRosterEdit();}
function chooseMonth(value:string){setMonth(value);setSelected(dateInMonth(selected,value));}
function move(n:number){if(view==='Week'){const d=addDays(selected,n*7);setSelected(d);setMonth(d.slice(0,7));return;}const d=new Date(start+'T12:00:00');d.setMonth(d.getMonth()+n);chooseMonth(dateKey(d).slice(0,7));}
async function assign(id:string,ds=multi?dates:[selected]){if(!ds.length)return false;const saved=await mutate(shiftAssignmentChanges(s,id,ds),`${ds.length===1?fmt(ds[0]):ds.length+' dates'}: ${s.shifts.find((x:Shift)=>x.id===id)?.name||'shift removed'}`);if(!saved)return false;if(settings.haptics!==false)navigator.vibrate?.(10);notice(`${ds.length} ${ds.length===1?'day':'days'} updated`);setDates([]);setMulti(editMode&&!paint);return true;}
async function bulkAssign(id:string){if(s.shifts.find((sh:Shift)=>sh.id===id)?.category!=='Leave'&&dates.some(d=>resolveShift(s,d))&&!confirm(id?'Replace shifts on the selected dates? Events and notes will stay in place.':'Clear shifts on the selected dates? Events and notes will stay in place.'))return;await assign(id);}
function copyDates(cut:boolean){try{const block=copyBlock(s,dates,cut);setBlockClipboard(block);setPaint('');setMulti(false);pasteTarget(addDays(block.end,1));notice(cut?'Choose a destination, then tap Move here.':'Duties copied. Choose a destination, then paste or repeat.');}catch(e:any){notice(e.message);}}
async function pasteDates(){if(!blockClipboard)return;try{const target=selected;const changes=pasteBlock(s,blockClipboard,target);if(changes.some(c=>resolveShift(s,c.data.date))&&!confirm(blockClipboard.cut?'Move these duties to the destination? Source duties will be cleared and destination duties replaced. Notes, leave annotations and appointments stay on their dates.':'Paste these duties and replace duties on the affected dates? Notes, leave annotations and appointments stay on their dates.'))return;if(await mutate(changes,blockClipboard.cut?'Moved roster dates':'Pasted roster dates')){if(blockClipboard.cut){setBlockClipboard(undefined);setMulti(true);}else pasteTarget(addDays(target,Math.round((Date.parse(blockClipboard.end)-Date.parse(blockClipboard.start))/86400000)+1));setDates([]);notice('Duties saved. Notes and leave entries stayed on their dates.');}}catch(e:any){notice(e.message);}}
function repeatDates(){try{const sorted=[...dates].sort(),items=selectionPattern(s,dates);if(items.length!==new Set(dates).size&&!confirm('Repeat the full sequence from your first selected date to your last, including the days between them?'))return;setEditing({id:uid(),name:'My selected rotation',items,start:addDays(sorted[sorted.length-1],1),repeat:100});setModal('pattern');}catch(e:any){notice(e.message);}}
