function clickDate(date:string){if(paint&&suppressPaintClick.current){suppressPaintClick.current=false;return;}setSelected(date);setMonth(date.slice(0,7));if(paint&&writable){assign(paint==='__erase__'?'':paint,[date]);return;}if(multi){setDates(old=>old.includes(date)?old.filter(x=>x!==date):[...old,date]);return;}if(editMode||fitCalendar)return;if(window.innerWidth<1100)requestAnimationFrame(()=>document.getElementById('selected-day-panel-heading')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));}
async function settingsUpdate(update:any){await mutate([{kind:'settings',data:{...settings,...update}}],'Preferences updated');}
