function openRhythm(rhythm:any){try{const plan=planRotation(rhythm.style,rhythm.id,choices,editMode?selected:start,1);setEditing({...plan.pattern,repeat:0,id:uid(),templateShifts:plan.shiftsToCreate});setModal('pattern');}catch(error:any){notice(error.message);}}
function openShift(shift?:Shift){setEditing(shift||null);setModal('shift');}
function updateQuickDraft(event:Event){setQuickDrafts(old=>({...old,[draftKey]:event}));}
function clearQuickDraft(id?:string){setQuickDrafts(old=>{if(id&&old[draftKey]?.id!==id)return old;const next={...old};delete next[draftKey];return next;});}
function startQuickEntry(kind:'overtime'|'leave'|'note'){const pristine=quickDraft&&JSON.stringify(quickDraft)===JSON.stringify(fastEntryDraft(quickDraft.entryType==='overtime'?'overtime':quickDraft.entryType==='leave'?'leave':'note',quickDraft.date,quickDraft.id));if(quickDraft&&!pristine){setSelected(quickDraft.date);setMonth(quickDraft.date.slice(0,7));notice('Finish or cancel your current entry first.');if(fitCalendar)setModal('quick-entry');return;}updateQuickDraft(fastEntryDraft(kind,selected,uid()));if(fitCalendar)setModal('quick-entry');}
async function saveEntry(input:Event){const {_draft,...event}=input as Event&{_draft?:boolean};if(!await mutate([{kind:'event',id:event.id,data:event}],'Event: '+event.title))return false;clearQuickDraft(event.id);notice('Entry saved');return true;}
function openEvent(event?:Event){if(!event&&page==='Today')setSelected(now);setEditing(event||null);setModal('event');}
async function quickPattern(){const p={id:uid(),name:'2 days · 2 nights · 4 off',items:['day','day','night','night','off','off','off','off'],start,repeat:100};await mutate([{kind:'pattern',id:p.id,data:p}],'Applied 8-day rotation ×100');notice('800 days planned, ready to edit');}
function activePattern(){return [...s.patterns].reverse().find((p:Pattern)=>selected>=p.start&&(!p.until||selected<=p.until)&&(p.repeat===0||(Date.parse(selected)-Date.parse(p.start))/86400000<p.items.length*p.repeat));}
function editRotationFromDay(){const original=activePattern();if(!original)return;const elapsed=(Date.parse(selected)-Date.parse(original.start))/86400000,offset=elapsed%original.items.length;setEditing({...original,id:uid(),name:original.name+' · updated',items:[...original.items.slice(offset),...original.items.slice(0,offset)],start:selected,repeat:0,until:original.until||(original.repeat?addDays(original.start,original.items.length*original.repeat-1):undefined),splitFromPatternId:original.id});setModal('pattern');}
