useEffect(()=>{if(!s||modal||api.pendingCount||api.error||['Loading','Checking for updates'].includes(api.status))return;const url=new URL(location.href);if(url.searchParams.has('invite')||url.searchParams.has('install')||url.searchParams.has('action')||url.searchParams.has('date'))return;const key='shiftly-intro-v1:'+String(identity?.id||'guest');try{if(localStorage.getItem(key))return;localStorage.setItem(key,'1');setModal('intro');}catch{}},[s?.calendar.id,modal,api.status]);
